import '@design-schema/lit';
import { html, type TemplateResult } from 'lit';
import type { StackAlign, StackDirection, StackElement, StackGap, StackJustify } from '@design-schema/lit';

interface StackArgs {
  direction: StackDirection;
  gap: StackGap;
  align: StackAlign;
  justify: StackJustify;
  wrap: boolean;
  element: StackElement;
}

function renderStack(args: StackArgs, content: TemplateResult): TemplateResult {
  return html`
    <ds-stack
      direction=${args.direction}
      gap=${args.gap}
      align=${args.align}
      justify=${args.justify}
      ?wrap=${args.wrap}
      .element=${args.element}
    >
      ${content}
    </ds-stack>
  `;
}

const buttons: TemplateResult = html`
  <ds-button label="Save changes"></ds-button>
  <ds-button variant="secondary" label="Preview"></ds-button>
  <ds-button variant="ghost" label="Cancel"></ds-button>
`;

html`
  <div style="max-inline-size: 16rem">${renderStack({ direction: 'horizontal', align: 'center', wrap: true }, buttons)}</div>
`;

